using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;

// PROGRAM: Membandingkan Kecepatan & Alokasi Memori: Boxing vs Generics
const int Iterations = 2_000_000;

// 1. Menggunakan ArrayList (Memicu 2 Juta Kali Boxing di Heap)
GC.Collect();
long memBefore1 = GC.GetTotalMemory(true);
var sw1 = Stopwatch.StartNew();

ArrayList arrayList = new ArrayList();
for (int i = 0; i < Iterations; i++)
{
    arrayList.Add(i); // BOXING!
}
sw1.Stop();
long memAfter1 = GC.GetTotalMemory(false);

Console.WriteLine($"[ArrayList (Boxing)] Waktu: {sw1.ElapsedMilliseconds} ms | Memori Terpakai: {(memAfter1 - memBefore1) / (1024 * 1024)} MB");

// 2. Menggunakan List<int> (Zero Boxing, Type-Safe)
GC.Collect();
long memBefore2 = GC.GetTotalMemory(true);
var sw2 = Stopwatch.StartNew();

List<int> genericList = new List<int>(Iterations);
for (int i = 0; i < Iterations; i++)
{
    genericList.Add(i); // ZERO BOXING!
}
sw2.Stop();
long memAfter2 = GC.GetTotalMemory(false);

Console.WriteLine($"[List<int> (Generics)] Waktu: {sw2.ElapsedMilliseconds} ms | Memori Terpakai: {(memAfter2 - memBefore2) / (1024 * 1024)} MB");

