using System;

public class SafeUnboxer
{
    public static int ExtractInteger(object? boxedValue, int fallbackDefault)
    {
        if (boxedValue is int directInt)
        {
            return directInt;
        }

        if (boxedValue is string str && int.TryParse(str, out int parsed))
        {
            return parsed;
        }

        return fallbackDefault;
    }

    public static void Main()
    {
        object objInt = 42;
        object objStr = "100";
        object objBad = DateTime.Now;

        Console.WriteLine(ExtractInteger(objInt, -1));
        Console.WriteLine(ExtractInteger(objStr, -1));
        Console.WriteLine(ExtractInteger(objBad, -1));
    }
}
